-- -----------------------------------------------------------------------------
-- This script creates the following tables for Module 1 (Identity & Sites):
--   - site         (R01) - Gym branches/locations
--   - app_user     (R02) - Core user accounts, authentication & system roles
--   - trainer      (R03) - Trainer profiles, including specialty ('ROOM_CHIEF')
--   - client       (R04) - Client profiles associated with a gym site
--
-- Design notes:
--   - Follows 1:1 table inheritance for user specializations (trainer, client).
--   - Primary keys use INTEGER GENERATED BY DEFAULT AS IDENTITY for root entities,
--     and FK integer primary keys for 1:1 subtype tables.
--   - 'ROOM_CHIEF' is integrated as a trainer specialty per updated domain rules.
--   - Follows 3NF, referential integrity and approved naming conventions.
-- -----------------------------------------------------------------------------

BEGIN;

-- -----------------------------------------------------------------------------
-- Table: site
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS site (
    id_site               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                  VARCHAR(100)        NOT NULL,
    address               TEXT                NOT NULL,
    registration_date     DATE                NOT NULL DEFAULT CURRENT_DATE,

    CONSTRAINT uq_site_name
        UNIQUE (name),

    CONSTRAINT chk_site_name_not_empty
        CHECK (TRIM(name) <> ''),

    CONSTRAINT chk_site_address_not_empty
        CHECK (TRIM(address) <> '')
);

COMMENT ON TABLE  site IS 'Gym branches/locations where clients are enrolled.';
COMMENT ON COLUMN site.id_site           IS 'Primary key of the site.';
COMMENT ON COLUMN site.name              IS 'Unique name of the gym site.';
COMMENT ON COLUMN site.address           IS 'Physical address of the site.';
COMMENT ON COLUMN site.registration_date IS 'Date the site was registered in the system.';


-- -----------------------------------------------------------------------------
-- Table: app_user
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_user (
    id_user               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                  VARCHAR(150)        NOT NULL,
    email                 VARCHAR(255)        NOT NULL,
    password_hash         VARCHAR(255)        NOT NULL,
    role                  VARCHAR(20)         NOT NULL,
    registration_date     DATE                NOT NULL DEFAULT CURRENT_DATE,

    CONSTRAINT uq_app_user_email
        UNIQUE (email),

    CONSTRAINT chk_app_user_name_not_empty
        CHECK (TRIM(name) <> ''),

    CONSTRAINT chk_app_user_email_not_empty
        CHECK (TRIM(email) <> ''),

    CONSTRAINT chk_app_user_role
        CHECK (role IN ('ADMIN', 'TRAINER', 'CLIENT'))
);

COMMENT ON TABLE  app_user IS 'Core user accounts table storing credentials and system roles (RBAC).';
COMMENT ON COLUMN app_user.id_user           IS 'Primary key of the user.';
COMMENT ON COLUMN app_user.name              IS 'Full name of the user.';
COMMENT ON COLUMN app_user.email             IS 'Unique email address used for authentication.';
COMMENT ON COLUMN app_user.password_hash     IS 'Securely hashed password (bcrypt/argon2).';
COMMENT ON COLUMN app_user.role              IS 'System role for authorization (ADMIN, TRAINER, CLIENT).';
COMMENT ON COLUMN app_user.registration_date IS 'Date the account was created.';


-- -----------------------------------------------------------------------------
-- Table: trainer
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS trainer (
    id_trainer            INTEGER             PRIMARY KEY,
    specialty             VARCHAR(50)         NOT NULL DEFAULT 'GENERAL',

    CONSTRAINT fk_trainer_app_user
        FOREIGN KEY (id_trainer)
        REFERENCES app_user (id_user)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,

    CONSTRAINT chk_trainer_specialty_not_empty
        CHECK (TRIM(specialty) <> '')
);

COMMENT ON TABLE  trainer IS 'Trainer profiles extending app_user (1:1). Stores specialization details.';
COMMENT ON COLUMN trainer.id_trainer IS 'Primary key and foreign key referencing app_user(id_user).';
COMMENT ON COLUMN trainer.specialty  IS 'Trainer specialization or rank (e.g. GENERAL, HIPERTROFIA, CARDIO, ROOM_CHIEF).';


-- -----------------------------------------------------------------------------
-- Table: client
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS client (
    id_client             INTEGER             PRIMARY KEY,
    age                   INTEGER             NOT NULL,
    id_site               INTEGER             NOT NULL,

    CONSTRAINT fk_client_app_user
        FOREIGN KEY (id_client)
        REFERENCES app_user (id_user)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,

    CONSTRAINT fk_client_site
        FOREIGN KEY (id_site)
        REFERENCES site (id_site)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,

    CONSTRAINT chk_client_age
        CHECK (age >= 14 AND age <= 100)
);

-- Indexes for common lookups and FK checks.
-- PostgreSQL does not index foreign key columns automatically, so every FK
-- column that is not already a leading column of a primary/unique key gets one.
CREATE INDEX IF NOT EXISTS idx_client_site ON client (id_site);

COMMENT ON TABLE  client IS 'Client profiles extending app_user (1:1). Linked to a specific gym site.';
COMMENT ON COLUMN client.id_client IS 'Primary key and foreign key referencing app_user(id_user).';
COMMENT ON COLUMN client.age       IS 'Age of the client (valid between 14 and 100).';
COMMENT ON COLUMN client.id_site   IS 'Gym site where the client is enrolled (FK to site).';

COMMIT;
